<?php
$root=$argv[1];$stage=$argv[2];require $root.'/vendor/autoload.php';$app=require $root.'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\{DB,Schema,Queue,Mail,Http,Hash,Validator};use Illuminate\Database\Schema\Blueprint;use App\Models\{User,Pdv};use App\Services\PdvService;
config(['database.default'=>'pdv_strict_memory','database.connections.pdv_strict_memory'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true],'cache.default'=>'array']);DB::setDefaultConnection('pdv_strict_memory');if(DB::connection()->getDriverName()!=='sqlite'||DB::connection()->getDatabaseName()!==':memory:')throw new RuntimeException('Memory guard failed');Queue::fake();Mail::fake();Http::preventStrayRequests();
Schema::create('users',function(Blueprint $t){$t->id();$t->string('name');$t->string('email')->unique();$t->string('password');$t->string('cpf',14)->unique();$t->date('birth_date');$t->string('phone',20);$t->string('gender',1)->nullable();$t->integer('type');$t->integer('pdv_id')->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('points_of_sale',function(Blueprint $t){$t->id();$t->string('name');foreach(['cnpj','address','phone','responsible','map_link'] as $c)$t->string($c)->nullable();$t->boolean('active')->default(true);$t->decimal('commission_percentage',5,2)->nullable();$t->integer('access_user_id')->nullable();$t->softDeletes();$t->timestamps();});
$n=0;$ok=function($v,$m)use(&$n){if(!$v)throw new RuntimeException($m);$n++;};
try{DB::table('users')->insert(['name'=>'QA','email'=>'before@example.test','password'=>'QA-only-hash','type'=>2]);throw new RuntimeException('Regression did not reproduce');}catch(Illuminate\Database\QueryException $e){$ok(str_contains($e->getMessage(),'cpf'),'original missing CPF error reproduced');}
$migration=require $stage.'/database/migrations/2026_11_04_235900_allow_pdv_accounts_without_personal_fields.php';$migration->up();
foreach(['cpf','birth_date','phone'] as $field){$info=collect(DB::select('PRAGMA table_info(users)'))->firstWhere('name',$field);$ok((int)$info->notnull===0,$field.' now optional for business account');}
$super=User::create(['name'=>'QA owner','email'=>'owner@example.test','password'=>'QA-owner-12345','cpf'=>'00000000001','birth_date'=>'1990-01-01','phone'=>'11000000000','type'=>1]);$svc=new PdvService;
$data=['name'=>'QA point','responsible'=>'QA staff','access_email'=>'point@example.test','password'=>'QA-point-12345','commission_percentage'=>20];$point=$svc->create($data,$super);$account=$point->accessUser;
$ok($account!==null,'account created');$ok($account->cpf===null&&$account->birth_date===null&&$account->phone===null,'no invented personal fields');$ok($account->type===2&&$account->pdv_id===$point->id,'business permissions preserved');$ok(Hash::check($data['password'],$account->password),'login password hashed and valid');$ok(app('auth')->getProvider()->validateCredentials($account,['password'=>$data['password']]),'login provider accepts business account');$serialized=(new App\Http\Resources\UserResource($account))->resolve(Illuminate\Http\Request::create('/qa'));$ok($serialized['cpf']===null&&$serialized['birth_date']===null,'login resource accepts absent personal fields');$ok($point->commission_percentage==='20.00','commission preserved');
$second=$svc->create([...$data,'access_email'=>'point2@example.test'],$super);$ok($second->accessUser->cpf===null,'second point allowed without fake CPF');
$legacy=Pdv::create(['name'=>'QA legacy','responsible'=>'QA legacy staff']);$legacy=$svc->update($legacy,['responsible'=>'QA legacy staff','access_email'=>'legacy@example.test','password'=>'QA-legacy-12345'],$super);$ok($legacy->accessUser!==null,'existing point can gain access in edit');$ok($legacy->accessUser->type===2&&$legacy->accessUser->pdv_id===$legacy->id,'edit linked correct PDV');
$hash=$account->password;$updated=$svc->update($point,['responsible'=>'QA updated','access_email'=>'point@example.test'],$super);$ok($updated->accessUser->password===$hash,'edit without password keeps credentials');
try{$svc->create([...$data,'access_email'=>'point@example.test'],$super);throw new RuntimeException('Duplicate email accepted');}catch(Illuminate\Validation\ValidationException $e){$ok(isset($e->errors()['access_email']),'duplicate email rejected');}
$customerRules=(new App\Http\Requests\StoreUserRequest)->rules();foreach(['cpf','birth_date','phone'] as $field){$ok(Validator::make([],[$field=>$customerRules[$field]])->fails(),'customer still requires '.$field);}
$before=$super->fresh()->only(['cpf','birth_date','phone']);$ok($before['cpf']==='00000000001'&&$before['phone']==='11000000000','existing personal data preserved');
try{$migration->down();throw new RuntimeException('Unsafe rollback accepted');}catch(RuntimeException $e){$ok(str_contains($e->getMessage(),'Cannot restore'),'rollback refuses data loss');}
$ok(User::whereNull('cpf')->count()===3,'rollback leaves business accounts intact');Mail::assertNothingSent();$ok(true,'no email sent');
echo 'PASS '.$n.' strict-schema PDV checks; SQLite memory only, fake queues/mail, no real access created.'.PHP_EOL;
